const normalizar = (valor) => String(valor ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const row = $input.first().json;
const empresa = String(row['Empresa / Negócio'] ?? '').trim();
const telefone = String(row['Telefone / WhatsApp'] ?? '').replace(/\D/g, '');
const telefoneFinal = telefone.startsWith('55') ? telefone : `55${telefone}`;
const nicho = normalizar(row['Nicho / Categoria']);
const statusSite = normalizar(row['Status do Site Atual']);
const statusAbordagem = normalizar(row['Status da Abordagem']);
const nichosPermitidos = ['engenheiros', 'arquitetos', 'esteticas', 'clinicas', 'servicos juridicos'];
const statusSiteBloqueados = ['-', 'oferecer site novo', 'site fora do ar', 'oferecer site novo / site lento'];
const abordagensConcluidas = ['entrei em contato', 'nao quis continuar', 'aguardando resposta', 'inicio do projeto', 'testes', 'aprovado'];
const elegivel = nichosPermitidos.includes(nicho) && statusSite === 'sem site' && !statusSiteBloqueados.includes(statusSite) && (!statusAbordagem || statusAbordagem === '-') && telefoneFinal.length >= 12 && telefoneFinal.length <= 13;
if (!elegivel || abordagensConcluidas.includes(statusAbordagem)) return [];
const hora = Number($now.setZone('America/Sao_Paulo').toFormat('H'));
const saudacao = hora < 12 ? 'Bom dia' : hora < 18 ? 'Boa tarde' : 'Boa noite';
const mensagens = {
  'servicos juridicos': `${saudacao}, ${empresa}! Tudo bem?\n\nEstava pesquisando por serviços jurídicos na região e vi que vocês têm uma reputação excelente, mas notei que ainda não possuem um site oficial cadastrado.\n\nNós da GB Softwares desenvolvemos páginas de alta performance para o setor de advocacia, e eu montei uma prévia visual da estrutura oficial do seu escritório, já aplicando a identidade e as cores de vocês.`,
  esteticas: `${saudacao}, ${empresa}! Tudo bem?\n\nEstava pesquisando por clínicas de saúde / estética na região e vi que vocês têm uma reputação excelente, mas notei que ainda não possuem um site oficial cadastrado.\n\nNós da GB Softwares desenvolvemos páginas de alta performance para o setor de saúde / estética, e eu montei uma prévia visual da estrutura oficial da sua clínica, já aplicando a identidade e as cores de vocês.`,
  clinicas: `${saudacao}, ${empresa}! Tudo bem?\n\nEstava pesquisando por clínicas de saúde / estética na região e vi que vocês têm uma reputação excelente, mas notei que ainda não possuem um site oficial cadastrado.\n\nNós da GB Softwares desenvolvemos páginas de alta performance para o setor de saúde / estética, e eu montei uma prévia visual da estrutura oficial da sua clínica, já aplicando a identidade e as cores de vocês.`,
  arquitetos: `${saudacao}, ${empresa}! Tudo bem?\n\nEstava pesquisando por Arquitetos / Engenheiros na região e vi que vocês têm uma reputação excelente, mas notei que ainda não possuem um site oficial cadastrado.\n\nNós da GB Softwares desenvolvemos páginas de alta performance para o setor de arquitetura e engenharia, e eu montei uma prévia visual da estrutura oficial do seu escritório, já aplicando a identidade e as cores de vocês.`,
  engenheiros: `${saudacao}, ${empresa}! Tudo bem?\n\nEstava pesquisando por Arquitetos / Engenheiros na região e vi que vocês têm uma reputação excelente, mas notei que ainda não possuem um site oficial cadastrado.\n\nNós da GB Softwares desenvolvemos páginas de alta performance para o setor de arquitetura e engenharia, e eu montei uma prévia visual da estrutura oficial do seu escritório, já aplicando a identidade e as cores de vocês.`
};
const delayMs = Math.floor(Math.random() * 180001) + 120000;
return [{ json: { ...row, telefoneNormalizado: telefoneFinal, mensagem: mensagens[nicho], delayMs, delaySeconds: Math.ceil(delayMs / 1000) } }];
